<main class="content"><section class="panel"><div class="panel-head"><div><h2>Tests y tabuladores</h2><p>Carga archivos o registra enlaces por asignatura.</p></div><button class="primary" data-open="resource-modal">+ Cargar recurso</button></div><div class="resource-list"><?php foreach($resources as $r):?><article><span class="file-icon"><?=$r['type']==='test'?'✓':'▦'?></span><div><small><?=e(strtoupper($r['type']))?> · <?=e($r['subject']??'General')?></small><b><?=e($r['name'])?></b><p><?=e($r['description'])?></p></div><div><?php if($r['external_link']):?><a href="<?=e($r['external_link'])?>" target="_blank">Abrir enlace</a><?php endif;?><form method="post" action="<?=url('/admin/recursos/eliminar')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger">Eliminar</button></form></div></article><?php endforeach;?></div></section><dialog id="resource-modal"><form method="post" enctype="multipart/form-data" action="<?=url('/admin/recursos/guardar')?>" class="modal-form"><?=csrf_field()?><div class="modal-head"><h2>Nuevo recurso</h2><button type="button" data-close>×</button></div><div class="form-grid"><label>Tipo<select name="type"><option value="test">Test</option><option value="tabulador">Tabulador</option></select></label><label>Nombre<input required name="name"></label><label class="wide">Descripción<textarea name="description" rows="3"></textarea></label><label>Asignatura<select name="subject_id"><option value="">Todas</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><label>Grupo<select name="group_id"><option value="">Sin grupo</option><?php foreach($groups as $g):?><option value="<?=$g['id']?>"><?=e($g['name'])?></option><?php endforeach;?></select></label><label>Subgrupo<select name="subgroup_id"><option value="">Sin subgrupo</option><?php foreach($subgroups as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><label>Archivo<input type="file" name="file"></label><label>Nombre / Link<input type="url" name="external_link" placeholder="https://..."></label><input type="hidden" name="active" value="1"></div><button class="primary">Guardar recurso</button></form></dialog></main>

